import{_ as a,o as t,c as s,ah as r}from"./chunks/framework.Cx6lfSeA.js";const u=JSON.parse('{"title":"Auto-Renderers","description":"Auto-generate tables, charts, forms, metrics, and timelines from raw data with autoTable, autoChart, autoForm, and autoMetrics.","frontmatter":{"description":"Auto-generate tables, charts, forms, metrics, and timelines from raw data with autoTable, autoChart, autoForm, and autoMetrics.","head":[["link",{"rel":"canonical","href":"https://max-health-inc.github.io/prefab/guide/auto-renderers"}],["meta",{"property":"og:url","content":"https://max-health-inc.github.io/prefab/guide/auto-renderers"}],["meta",{"property":"og:description","content":"Auto-generate tables, charts, forms, metrics, and timelines from raw data with autoTable, autoChart, autoForm, and autoMetrics."}]]},"headers":[],"relativePath":"guide/auto-renderers.md","filePath":"guide/auto-renderers.md","lastUpdated":1782582949000}'),o={name:"guide/auto-renderers.md"};function n(i,e,h,l,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /prefab/guide/auto-renderers.md for this page in Markdown format</div><h1 id="auto-renderers" tabindex="-1">Auto-Renderers <a class="header-anchor" href="#auto-renderers" aria-label="Permalink to &quot;Auto-Renderers&quot;">​</a></h1><p>Most of the time you already have the data — a list of users from a query, a few KPIs, a row of monthly sales. What you <em>don&#39;t</em> want to do is hand-wire a table, pick column definitions, choose a chart type, and style badges every single time. Auto-renderers close that gap: hand them raw data, get a finished UI back in one call.</p><h2 id="the-mental-model" tabindex="-1">The Mental Model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The Mental Model&quot;">​</a></h2><p>Think of an auto-renderer as a single function with a simple shape: <strong>data in → component tree out.</strong></p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> users</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SELECT * FROM users&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">autoTable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(users), { title: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Users&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>That <code>autoTable(users)</code> call inspects your data, infers the columns from the object keys, detects which fields are statuses (and renders them as badges), and returns a normal <code>Component</code>. Because the output is just a regular component, it slots into any layout — wrap it in a <code>Column</code>, drop it next to a chart, or hand it to <code>display()</code>. There is no special runtime and no escape hatch to learn.</p><p>The family follows one consistent convention: the <strong>first argument is your data</strong>, and an <strong>optional second argument is an options object</strong> (title, layout hints, behaviour flags). <code>autoForm</code> is the small exception — it takes a submit-tool name in the middle so a generated form knows which MCP tool to call.</p><p>A useful way to picture the whole family is by the shape of input each one expects. Roughly:</p><ul><li>a <strong>single object</strong> describes one thing → a detail view,</li><li>a <strong>list of records</strong> describes many of the same thing → a table, chart, or comparison,</li><li>a <strong>sequence in time</strong> describes a journey → a timeline or progress tracker,</li><li>a <strong>set of fields</strong> describes an intent to capture → a form.</li></ul><p>Once you internalise that mapping, choosing the right helper rarely needs the reference at all — you reach for the one whose input shape matches the data already in your hand.</p><h2 id="when-to-reach-for-them" tabindex="-1">When to Reach for Them <a class="header-anchor" href="#when-to-reach-for-them" aria-label="Permalink to &quot;When to Reach for Them&quot;">​</a></h2><p>Auto-renderers shine when the <em>structure</em> of your UI mirrors the <em>structure</em> of your data:</p><ul><li>An array of records → a searchable, sortable table.</li><li>A handful of numbers → a row of metric cards.</li><li>Date-stamped events → a vertical timeline.</li><li>A list of fields → a working form wired to a tool.</li></ul><p>They are perfect for MCP tool handlers, where you frequently turn an API response straight into something renderable with minimal ceremony.</p><h2 id="when-to-hand-craft-instead" tabindex="-1">When to Hand-Craft Instead <a class="header-anchor" href="#when-to-hand-craft-instead" aria-label="Permalink to &quot;When to Hand-Craft Instead&quot;">​</a></h2><p>Reach for the underlying components directly when you need precise control — bespoke column renderers, custom interactions, conditional layouts, or a design that doesn&#39;t map cleanly onto your raw data shape. Auto-renderers are a fast on-ramp, not a ceiling: you can start with <code>autoTable</code>, then graduate to a hand-built <code>DataTable</code> the moment you need something the auto path can&#39;t express. The two styles compose freely in the same view.</p><p>→ See the <a href="/prefab/reference/api/auto/">Auto-Renderers API reference</a> for the full API: every helper, its options, and examples.</p>`,18)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
